﻿using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// Options that use the default reflection-based resolver
var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);

// --- 1. GetTypeInfo<T>(): strongly-typed metadata retrieval ---
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"GetTypeInfo<Person> → Type = {personInfo.Type.Name}");

string json = JsonSerializer.Serialize(new Person("Ada", 37), personInfo);
Console.WriteLine($"Serialized: {json}");

// --- 2. TryGetTypeInfo<T>(): check-without-throwing ---
// Person should resolve fine (reflection resolver handles any type)
if (options.TryGetTypeInfo<Person>(out JsonTypeInfo<Person>? info))
    Console.WriteLine($"TryGetTypeInfo<Person> succeeded → {info!.Type.Name}");
else
    Console.WriteLine("TryGetTypeInfo<Person> returned false");

// With a source-gen-only options instance (no resolver for UnknownType),
// TryGetTypeInfo returns false instead of throwing.
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = new EmptyResolver()
};

if (limited.TryGetTypeInfo<Person>(out _))
    Console.WriteLine("TryGetTypeInfo<Person> on limited options → found (unexpected)");
else
    Console.WriteLine("TryGetTypeInfo<Person> on limited options → not found (expected)");

Console.WriteLine("Done.");

// --- Types ---
public record Person(string Name, int Age);

/// A resolver that deliberately resolves nothing, simulating a restricted context.
file sealed class EmptyResolver : IJsonTypeInfoResolver
{
    public JsonTypeInfo? GetTypeInfo(Type type, JsonSerializerOptions options) => null;
}

